'use strict';

const path = require('node:path');
const fs = require('node:fs');
const { spawn } = require('node:child_process');

function deleteLockFiles(ctx, cds) {
  const dirs = new Set();
  for (const p of ctx.project.packageJsonFiles || []) dirs.add(path.dirname(p));
  for (const d of dirs) {
    const f = path.join(d, 'package-lock.json');
    if (fs.existsSync(f)) fs.unlinkSync(f);
  }
  for (const name of ['npm-shrinkwrap.json', 'yarn.lock']) {
    const f = path.join(cds.root, name);
    if (fs.existsSync(f)) fs.unlinkSync(f);
  }
}

function runCommand(cmd, args, cwd) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { cwd, stdio: 'inherit', shell: false });
    child.on('exit', code => resolve(code ?? 1));
    child.on('error', () => resolve(1));
  });
}

// Which package.json directories does a root `npm install` NOT cover?
// A tracked package.json is covered by root install iff (a) it lives inside
// cds.root and (b) the root package.json's `workspaces` array reaches it via
// collectWorkspacePackageJsons. Anything else (e.g. mtx/sidecar outside the
// workspaces glob) needs its own install.
async function extraInstallDirs(ctx, cds) {
  const rootPkg = path.join(cds.root, 'package.json');
  let covered;
  try {
    const { collectWorkspacePackageJsons } = require('../util/workspaces');
    covered = new Set((await collectWorkspacePackageJsons(cds)).map(p => path.resolve(p)));
  } catch {
    covered = new Set([path.resolve(rootPkg)]);
  }
  const dirs = [];
  for (const p of ctx.project.packageJsonFiles || []) {
    const resolved = path.resolve(p);
    if (resolved === path.resolve(rootPkg)) continue;
    if (covered.has(resolved)) continue;
    dirs.push(path.dirname(resolved));
  }
  return dirs;
}

async function runNpmInstalls(ctx, cds) {
  const rootCode = await runCommand('npm', ['install'], cds.root);
  if (rootCode !== 0) return rootCode;
  const extras = await extraInstallDirs(ctx, cds);
  for (const dir of extras) {
    const code = await runCommand('npm', ['install'], dir);
    if (code !== 0) return code;
  }
  return 0;
}

async function runInstall(ctx, cds) {
  const { askYesNo, NonTTYError } = require('../util/prompt');
  const { error } = require('../../../lib/util/term');
  let nodeRan = false, javaRan = false, aborted = false;

  const mismatches = ctx.verifyMismatches || [];
  const nodeWorkPending = !!ctx.rewriteRan || mismatches.some(m => m.scope === 'node');
  const javaWorkPending = !!ctx.rewriteRan || mismatches.some(m => m.scope === 'java');

  if (ctx.project.isNode && nodeWorkPending) {
    let accept = false, asked = true;
    try { accept = await askYesNo('Delete lock files and run `npm install` now?'); }
    catch (e) {
      if (e instanceof NonTTYError) asked = false;
      else throw e;
    }
    if (accept) {
      deleteLockFiles(ctx, cds);
      const code = await runNpmInstalls(ctx, cds);
      nodeRan = true;
      if (code !== 0) {
        console.log(error('✗ npm install failed. Please resolve and re-run.'));
        aborted = true;
      }
    } else if (asked) {
      console.log('To finish, delete lock files and run: npm install');
    }
  }

  if (ctx.project.isJava && javaWorkPending && !aborted) {
    let accept = false, asked = true;
    try { accept = await askYesNo('Run `mvn -N clean install` now?'); }
    catch (e) {
      if (e instanceof NonTTYError) asked = false;
      else throw e;
    }
    if (accept) {
      const code = await runCommand('mvn', ['-N', 'clean', 'install'], cds.root);
      javaRan = true;
      if (code !== 0) {
        console.log(error('✗ mvn install failed. Please resolve and re-run.'));
        aborted = true;
      }
    } else if (asked) {
      console.log('To finish, run: mvn -N clean install');
    }
  }

  ctx.installRan = nodeRan || javaRan;
  return { nodeRan, javaRan, aborted };
}

module.exports = { runInstall, deleteLockFiles, extraInstallDirs };
